"use client";

// One of Krystal's voice memos: a play/pause button with the transcript beneath it.
// Audio is pre-generated by agents/generate-audio.ts into public/audio.

import { useEffect, useRef, useState } from "react";

export function KrystalMemo({ title, audio, text }: { title: string; audio: string; text: string }) {
  const ref = useRef<HTMLAudioElement | null>(null);
  const [playing, setPlaying] = useState(false);

  useEffect(() => () => ref.current?.pause(), []);

  const toggle = () => {
    if (!ref.current) {
      ref.current = new Audio(`/audio/${audio}`);
      ref.current.onended = () => setPlaying(false);
    }
    if (playing) {
      ref.current.pause();
      setPlaying(false);
    } else {
      ref.current.play().then(() => setPlaying(true)).catch(() => setPlaying(false));
    }
  };

  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-center gap-3">
        <button type="button" onClick={toggle} className="pixel-button" aria-label={playing ? `Pause ${title}` : `Play ${title}`}>
          {playing ? "❚❚ Pause" : "▶ Play"}
        </button>
        <p className="font-pixel text-[10px] text-[var(--cc-accent)]">{title}</p>
      </div>
      <p className="text-sm italic leading-relaxed text-[var(--cc-muted)]">&ldquo;{text}&rdquo;</p>
    </div>
  );
}
